heaps/03_top_k_with_size_k_min_heap.algorithm:
top_k_largest(nums, k):
    heap = empty min-heap
    for each value in nums:
        if heap has fewer than k values: push value
        else if value > heap[0]: push value then pop the smallest   (the root is the gatekeeper)
    return heap sorted ascending
kth_largest(nums, k):
    return top_k_largest(nums, k)[0]   (the root of the size-k min-heap)

heaps/06_merge_k_sorted_arrays.algorithm:
merge_k_sorted(arrays):
    heap = empty list
    for each array index i:
        if arrays[i] is not empty: add (arrays[i][0], i, 0)   (skip empty arrays: no head to offer)
    heapify heap
    out = empty list
    while heap is not empty:
        (value, i, j) = pop the smallest
        append value to out
        if j + 1 < length of arrays[i]: push (arrays[i][j + 1], i, j + 1)
    return out
